    except (OSError, UnicodeError):
        pass

class ParseError(Exception):
    def __init__(self, source, pos, expected):
        self.source, self.pos, self.expected = source, pos, expected
    def text(self):
        pos = min(max(0, self.pos), len(self.source))
        line = self.source.count('\n', 0, pos) + 1
        begin = self.source.rfind('\n', 0, pos) + 1
        col = pos - begin + 1
        end = self.source.find('\n', begin)
        if end < 0: end = len(self.source)
        text = self.source[begin:end]
        margin = ' ' * (len(str(line)) + 1)
        return f' --> {line}:{col}\n{margin}|\n{line} | {text}\n{margin}| ' + ' '*(col-1) + '^---\n' + margin + '|\n' + margin + '= expected ' + self.expected + '\n'

@dataclass
class Seg:
    kind: str
    value: object
    quoted: bool = False

@dataclass
class Word:
