    kind: str
    value: object
    pos: int
    end: int
    extra: object = None

class Arithmetic:
    ranks = {'=':0, '==':1, '!=':1, '<':1, '>':1, '<=':1, '>=':1, '+':2, '-':2, '*':3, '/':3}
    def __init__(self, text):
