        elif op == '!=': n = int(x!=y)
        elif op == '<': n = int(x<y)
        elif op == '>': n = int(x>y)
        elif op == '<=': n = int(x<=y)
        else: n = int(x>=y)
        if n >= 2**63 or n < -2**63: n = (n+2**63) % 2**64 - 2**63
        return n

class Lexer:
    def __init__(self, source):
        self.s = source
        self.i = 0
        self.n = len(source)
        self.tokens = []
        self.pending = []
    def error(self, pos, expected): raise ParseError(self.s, pos, expected)
    def lit(self, segs, text, quoted=False):
        if segs and segs[-1].kind == 'lit' and segs[-1].quoted == quoted:
            segs[-1].value += text
        else: segs.append(Seg('lit', text, quoted))
    def paren(self, start):
        # Start is the opening parenthesis. Quoted regions and escaped
        # characters cannot terminate a nested command.
        j, depth, quote = start+1, 1, None
        while j < self.n:
            c = self.s[j]
            if c == '\\' and quote != "'": j += 2; continue
            if quote:
                if c == quote: quote = None
                j += 1; continue
            if c in ('"', "'", '`'): quote = c
            elif c == '(': depth += 1
            elif c == ')':
                depth -= 1
                if depth == 0: return j
            j += 1
        self.error(self.n, 'word, redirect_direction, heredoc, and_or_list_sep, or compound_list_sep')
    def parameter(self, quoted):
        begin = self.i
        if self.s.startswith('$((', begin):
            end = self.paren(begin+1)
            content = self.s[begin+3:end-1] if self.s[end-1:end] == ')' else None
            if content is not None:
                try:
                    a = Arithmetic(content)
                    self.i = end+1
                    return Seg('arith', a.tree, quoted)
                except ValueError: pass
        if self.s.startswith('$(', begin):
            end = self.paren(begin+1)
            content = self.s[begin+2:end]
            Parser(content).parse()
            self.i = end+1
            return Seg('cmd', content, quoted)
        if self.s.startswith('${', begin):
            j = begin+2
            nesting = 1
            quote = None
            while j < self.n:
                c = self.s[j]
                if c == '\\': j += 2; continue
                if quote:
                    if c == quote: quote = None
                elif c in ('"', "'"): quote = c
                elif self.s.startswith('${', j): nesting += 1; j += 1
                elif c == '}':
                    nesting -= 1
                    if not nesting: break
                j += 1
            if j >= self.n: self.error(j, 'param_op')
            content = self.s[begin+2:j]
            data = self.parse_parameter(content, begin+2)
            self.i = j+1
            return Seg('param', data, quoted)
