        if j >= self.n: self.error(j, 'var_name')
        if self.s[j] in '?$!#*@-': name = self.s[j]; j += 1
        elif self.s[j].isdigit():
            m = re.match('[0-9]+', self.s[j:]); name=m.group(); j+=len(name)
