    def parse_parameter(self, c, base):
        length = c.startswith('#')
        p = 1 if length else 0
        m = re.match(r'(?:[A-Za-z_][A-Za-z_0-9]*|[0-9]+|[?$!#*@-])', c[p:])
        if not m: self.error(base+p, 'var_name')
        name = m.group(); p += len(name)
        index = None
        if p < len(c) and c[p] == '[':
            end = c.find(']', p)
            if end < 0: self.error(base+len(c), 'assign')
            try: index = Arithmetic(c[p+1:end]).tree
            except ValueError: self.error(base+end, 'assign')
            p = end+1
        tail = c[p:]
        op, arg = None, None
        if tail:
            if tail.startswith((':-', ':=')):
                op, arg = tail[1], tail[2:]
            elif tail[0] in '-=':
                op, arg = tail[0], tail[1:]
            elif tail[0] == '/':
                op = 'replaceall' if tail.startswith('//') else 'replace'
                part = tail[2:] if op=='replaceall' else tail[1:]
                parts = part.split('/', 1)
                arg = (parts[0], parts[1] if len(parts)>1 else '')
            else: self.error(base+p, 'param_op')
        return (name, index, op, arg, length)
    def word(self):
        begin = self.i
        segs = []
        while self.i < self.n:
            c = self.s[self.i]
            if self.s.startswith(('<(', '>('), self.i):
                direction = c
                end = self.paren(self.i+1)
                inner = self.s[self.i+2:end]
                Parser(inner).parse()
                segs.append(Seg('proc', (direction, inner)))
                self.i = end+1
            elif c in ' \t\r\n;&|()<>{}': break
            elif c == '\\':
                if self.i+1 < self.n:
                    self.lit(segs, self.s[self.i+1], True); self.i += 2
                else: self.error(self.i+1, 'escaped_char')
            elif c == "'":
                end = self.s.find("'", self.i+1)
                if end < 0: self.error(self.n, 'single_quoted_span')
                self.lit(segs, self.s[self.i+1:end], True); self.i = end+1
            elif c == '"':
                self.i += 1
                self.lit(segs, '', True)
                while self.i < self.n and self.s[self.i] != '"':
                    x = self.s[self.i]
                    if x == '$': segs.append(self.parameter(True))
                    elif x == '`': segs.append(self.backtick(True))
                    elif x == '\\' and self.i+1 < self.n and self.s[self.i+1] in '$`"':
                        self.lit(segs, self.s[self.i+1], True); self.i += 2
                    else:
                        self.lit(segs, x, True); self.i += 1
                if self.i >= self.n:
                    self.error(self.n, 'command_span, backtick_span, expr_span, param_ex_span, param_span, or literal_in_double_quoted_span')
                self.i += 1
            elif c == '$': segs.append(self.parameter(False))
            elif c == '`': segs.append(self.backtick(False))
            elif c == '~' and self.i == begin:
                m = re.match(r'~[^\s/;&|()<>\{\}\"\x27$]*', self.s[self.i:])
                text = m.group()
                segs.append(Seg('tilde', text[1:])); self.i += len(text)
            else:
                self.lit(segs, c); self.i += 1
