    def backtick(self, quoted):
        begin = self.i
        self.i += 1
        content = ''
        while self.i < self.n and self.s[self.i] != '`':
            if self.s[self.i] == '\\' and self.i+1 < self.n and self.s[self.i+1] in '`$\\':
                self.i += 1
            content += self.s[self.i]; self.i += 1
        if self.i == self.n: self.error(self.n, 'backtick_span')
        self.i += 1
        Parser(content).parse()
        return Seg('cmd', content, quoted)
    def lex(self):
        need_marker = None
        while self.i < self.n:
            c = self.s[self.i]
            if c in ' \t\r': self.i += 1; continue
            if c == '#':
                j = self.s.find('\n', self.i)
                self.i = self.n if j < 0 else j
                continue
            start = self.i
            if c == '\n':
                self.i += 1
                self.tokens.append(Token('\n', '\n', start, self.i))
                for redir, marker in self.pending:
                    content = ''
                    while self.i < self.n:
                        e = self.s.find('\n', self.i)
                        if e < 0: e = self.n
                        line = self.s[self.i:e]
                        self.i = min(self.n, e+1)
                        if line == marker: break
                        content += line + ('\n' if e < self.n else '')
                    redir.extra = content
                self.pending = []
                continue
            if self.s.startswith(('<(', '>('), self.i):
                w = self.word(); self.tokens.append(Token('word', w, start, self.i)); continue
            red = re.match(r'(\d*)(<<|>>|<>|>\||<&|>&|<|>)', self.s[self.i:])
            if red:
                self.i += len(red.group())
                t = Token('redir', (red.group(1), red.group(2)), start, self.i)
                self.tokens.append(t)
                if red.group(2) == '<<': need_marker = t
                continue
            op = next((v for v in ('&&','||',';;',';&',';','&','|','(',')','{','}') if self.s.startswith(v, self.i)), None)
            if op:
                if need_marker: self.error(start, 'heredoc_marker')
                self.i += len(op)
                self.tokens.append(Token(op,op,start,self.i)); continue
            w = self.word()
            if self.i == start: self.error(start, 'word')
            if need_marker:
                marker = w.plain()
                if marker is None or not re.fullmatch('[A-Za-z_0-9]+', marker): self.error(start, 'heredoc_marker')
                self.pending.append((need_marker, marker)); need_marker = None
            self.tokens.append(Token('word', w, start, self.i))
        if need_marker: self.error(self.n, 'heredoc_marker')
        self.tokens.append(Token('eof', '', self.n, self.n))
        return self.tokens

class Parser:
    reserved = {'then','elif','else','fi','do','done','esac','function'}
    def __init__(self, source):
        self.s = source
        self.ts = Lexer(source).lex()
        self.i = 0
    def tok(self, d=0): return self.ts[min(self.i+d, len(self.ts)-1)]
    def val(self, d=0):
        t = self.tok(d)
        return t.value.plain() if t.kind == 'word' else t.kind
    def pop(self): t=self.tok(); self.i+=1; return t
    def fail(self, expected, pos=None): raise ParseError(self.s, self.tok().pos if pos is None else pos, expected)
    def accept(self, val):
        if self.val() == val: return self.pop()
        return None
    def require(self, val, expected=None):
        if self.val() != val: self.fail(expected or val)
        return self.pop()
    def skipnl(self):
        while self.val() == '\n': self.pop()
    def parse(self):
        a = self.list(set())
        if self.tok().kind != 'eof': self.fail('EOI, command, or compound_list_sep')
        return a
    def list(self, stop):
        nodes=[]
        while True:
            while self.val() in (';','\n'): self.pop()
            if self.tok().kind=='eof' or self.val() in stop: break
            node=self.andor()
            if self.accept('&'): node=('background',node)
            elif self.val() not in (';','\n','eof') and self.val() not in stop:
                self.fail(WORD_END)
            nodes.append(node)
        return ('list',nodes)
    def andor(self):
        nodes=[(None,self.pipeline())]
        while self.val() in ('&&','||'):
            op=self.pop().kind; self.skipnl()
            if self.val()=='eof': self.fail('normal_newline or command')
            nodes.append((op,self.pipeline()))
        return ('andor',nodes)
    def pipeline(self):
        nodes=[self.command()]
        while self.accept('|'):
            self.skipnl()
            if self.val()=='eof': self.fail('normal_newline or command')
            nodes.append(self.command())
        return ('pipe',nodes)
    def command(self):
