            content=self.list({close}); self.require(close, 'word, redirect_direction, heredoc, and_or_list_sep, or compound_list_sep')
            n=('group' if start=='{' else 'subshell',content)
        elif self.tok().kind=='word' and self.val(1)=='(' and self.val(2)==')':
            name=self.pop().value.plain(); self.pop(); self.pop(); self.skipnl()
            body=self.command(); n=('function',name,body)
        elif v in self.reserved or self.tok().kind not in ('word',):
