        while self.accept('elif'):
            conds.append(self.list({'then'})); self.require('then')
            self.list({'elif','else','fi'})
        other=('list',[])
        if self.accept('else'): other=self.list({'fi'})
        if self.val()=='eof': self.fail('word, escaped_char, unescaped_char, literal_span, any_string_span, any_char_span, command_span, proc_subst_direction, backtick_span, expr_span, param_ex_span, param_span, double_quoted_span, single_quoted_span, redirect_direction, heredoc, elif_part, else_part, and_or_list_sep, or compound_list_sep',len(self.s)+1)
        self.require('fi')
        return ('if',conds,first,other)
    def for_command(self):
        self.pop(); p=self.tok().pos
        if self.val()=='(' and self.val(1)=='(':
            start=self.pop().end; self.pop(); exprstart=self.ts[self.i-1].end
            depth=0
            while self.tok().kind!='eof':
                if self.val()==')' and self.val(1)==')' and depth==0: break
                if self.val()=='(': depth+=1
                elif self.val()==')': depth-=1
                self.pop()
            end=self.tok().pos; self.require(')'); self.require(')')
            exprs=self.s[exprstart:end].split(';')
            if len(exprs)!=3: self.fail('arith_for_exprs',p)
            try: trees=[Arithmetic(e).tree if e.strip() else None for e in exprs]
            except ValueError: self.fail('assign',p)
            while self.val() in (';','\n'): self.pop()
