        name=self.pop().value.plain(); self.pop(); words=[]
        while self.tok().kind=='word' and self.val()!='do': words.append(self.pop().value)
        while self.val() in (';','\n'): self.pop()
        self.require('do'); body=self.list({'done'}); self.require('done')
        return ('for',name,words,body)
    def case_command(self):
