        return ('case',word,parts)
    def condition(self):
        self.pop(); ts=[]
        while self.val()!=']]':
            if self.tok().kind=='eof': self.fail('cond_op')
            ts.append(self.pop())
        self.pop()
        ops={'=','==','!=','-eq','-ne','-lt','-gt','-le','-ge'}
        def split_cond(items):
            for sep in ('||','&&'):
                for i,t in enumerate(items):
                    if t.kind==sep:
                        return (sep,split_cond(items[:i]),split_cond(items[i+1:]))
            if not items: return ('single', Word([Seg('lit','',True)]))
            if len(items)==1 and items[0].kind=='word': return ('single',items[0].value)
            if len(items)<3 or items[1].kind!='word' or items[1].value.plain() not in ops:
                self.fail('cond_op',items[1].pos if len(items)>1 else items[0].end)
            if len(items)>3: self.fail('cond_op',items[3].pos)
            return ('cmp',items[1].value.plain(),items[0].value,items[2].value)
        return ('condition',split_cond(ts))
    def assignment(self,w,local=False):
        m=re.match(r'^([A-Za-z_][A-Za-z_0-9]*)(?:\[[^\]]*\])?=',w.raw)
        if not m:
            if local:
                name=w.plain()
                if not name or not re.fullmatch('[A-Za-z_][A-Za-z_0-9]*',name): self.fail('var_name',w.pos)
                return (name,Word([Seg('lit','',True)],w.pos,w.end,''),False)
            return None
        name=m.group(1); size=len(m.group())
        segs=[Seg(s.kind,s.value,s.quoted) for s in w.segs]
