        segs[0].value=segs[0].value[size:]
        if segs[0].value=='': segs.pop(0)
        if not segs:
            if self.accept('('):
                words=[]
                while self.val()!=')':
                    if self.tok().kind=='\n': self.pop(); continue
                    if self.tok().kind!='word': self.fail(SPANS)
                    words.append(self.pop().value)
                self.pop(); return (name,words,True)
            self.fail(SPANS,w.end)
        # An unquoted tilde in an initializer starts its own expansion.
        if segs[0].kind=='lit' and not segs[0].quoted and segs[0].value.startswith('~'):
            val=segs.pop(0).value; parts=val.split('/',1)
            segs.insert(0,Seg('tilde',parts[0][1:]))
            if len(parts)>1: segs.insert(1,Seg('lit','/'+parts[1]))
        return (name,Word(segs,w.pos+size,w.end,w.raw[size:]),False)
    def simple(self):
        words=[]; assigns=[]; reds=[]; local=False
        if self.val()=='local': local=True; self.pop()
        while True:
            t=self.tok()
            if t.kind=='redir': reds.append(self.redirect()); continue
            if t.kind!='word': break
            w=self.pop().value
            a=self.assignment(w,local) if not words or local else None
            if a is not None: assigns.append(a)
            else: words.append(w)
        return ('simple',words,assigns,reds,local)
    def redirect(self):
        t=self.pop(); fd,op=t.value
        if self.tok().kind!='word': self.fail('heredoc_marker' if op=='<<' else 'word or redirect_to_fd')
        w=self.pop().value
        return (int(fd) if fd else (0 if op.startswith('<') else 1),op,w,t.extra)

class Flow(Exception):
    def __init__(self, kind, status=0): self.kind,self.status=kind,status

class ExpandError(Exception): pass

class Shell:
    def __init__(self, script=''):
        self.vars = dict(os.environ)
        self.exported = set(os.environ)
        self.scopes=[]
        self.functions={}
        self.aliases={}
        self.args=[]
        self.script=script
        self.status=0
        self.pid=os.getpid()
        self.last_bg=0
        self.prev_dir=os.getcwd()
        self.options=set()
        self.jobs={}
        self.proc_fds=[]
    def rawget(self,name):
        for scope in reversed(self.scopes):
            if name in scope: return scope[name]
        return self.vars.get(name)
    def get(self,name):
        v=self.rawget(name)
        if v is None:
            if 'u' in self.options:
                write(f"nsh: undefined variable `{name}'\n",2); raise Flow('exit',1)
            return ''
        return (v[0] if v else '') if isinstance(v,list) else v
    def put(self,name,value,local=False):
        if local and self.scopes: self.scopes[-1][name]=value; return
        for scope in reversed(self.scopes):
            if name in scope: scope[name]=value; return
        self.vars[name]=value
    def env(self, extra=None):
        d={k:str(self.get(k)) for k in self.exported if self.rawget(k) is not None}
        if extra: d.update({k:str(v) for k,v in extra.items()})
        return {k:v for k,v in d.items() if '\x00' not in k+v and '=' not in k}
    def home(self):
        return self.env().get('HOME') or pwd.getpwuid(os.getuid()).pw_dir
    def special(self,name):
        if name=='?': return str(self.status)
        if name=='$': return str(self.pid)
        if name=='!': return str(self.last_bg)
        if name=='#': return str(len(self.args))
        if name=='-': return ''
        if name in ('@','*'): return ' '.join(self.args)
        if name.isdigit():
            n=int(name)
            return self.script if n==0 else (self.args[n-1] if n<=len(self.args) else '')
        return self.get(name)
    def parameter_value(self, data):
        name,index,op,arg,length=data
        if length:
            v=self.rawget(name)
            if name in ('@','*'): return str(len(self.args))
            return str(len(v) if v is not None else 0)
        v=self.special(name)
        if index is not None:
            a=self.rawget(name); i=Arithmetic.evaluate(index,self)
            v=a[i] if isinstance(a,list) and 0<=i<len(a) else ''
        if op in ('-','=') and self.rawget(name) is None:
            v=self.expand_text(arg)
            if op=='=': self.put(name,v)
        elif op in ('replace','replaceall'):
            pat,repl=arg
            pat=self.expand_text(pat); repl=self.expand_text(repl)
            expression=fnmatch.translate(pat)
            expression=expression.removeprefix('(?s:').removesuffix(')\\Z')
            try: v=re.sub(expression,lambda _:repl,v,count=0 if op=='replaceall' else 1,flags=re.S)
            except re.error: pass
        return v
    def expand_text(self,s):
        lex=Lexer(s)
        # Text in a parameter operator is one shell word, including spaces.
        try:
            pieces=[]
            while lex.i<lex.n:
                if s[lex.i] in ' \t\n': pieces.append(s[lex.i]); lex.i+=1
                else:
                    w=lex.word()
                    if not w.segs: pieces.append(s[lex.i]); lex.i+=1
