    def split(self,value):
        ifs=self.get('IFS') if self.rawget('IFS') is not None else ' \t\n'
        return re.split('['+re.escape(ifs)+']',value) if ifs else [value]
    def expand(self, word, globbing=True):
        results=[]; current=''; present=False; pattern=''; active=False
        def literal_pattern(text):
            return ''.join('[[]' if ch=='[' else '[*]' if ch=='*' else '[?]' if ch=='?' else ch for ch in text)
        def flush():
            nonlocal current,present,pattern,active
            if present:
                if active and globbing:
                    matches=sorted(glob.glob(pattern))
                    if not matches:
                        write('nsh: error: no matches\n',2); raise ExpandError()
                    results.extend(matches)
                else: results.append(current)
            current=''; present=False; pattern=''; active=False
        for s in word.segs:
